    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let misplaced = false
  const refs = []
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Error('syntax') }
  const rangeNode = (w1, w2) => {
    const a = parseAddr(w1), b = parseAddr(w2)
    if (a && b) refs.push({ a, b })
    return { t: 'range', a, b }
  }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const tk = toks[p++]
    if (tk.t === 'num') return { t: 'num', v: tk.v }
    if (tk.t === 'op') {
      if (tk.v === '(') { const e = cmp(); if (!isOp(')')) fail(); p++; return e }
      fail()
    }
    const up = tk.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++; return { t: 'call', name: up, args } }
      for (;;) {
        if (p + 3 < toks.length && toks[p].t === 'word' && toks[p + 1].t === 'op' && toks[p + 1].v === ':' && toks[p + 2].t === 'word' &&
          toks[p + 3].t === 'op' && (toks[p + 3].v === ',' || toks[p + 3].v === ')')) {
          args.push(rangeNode(toks[p].v, toks[p + 2].v)); p += 3
        } else args.push(cmp())
        if (isOp(',')) { p++; continue }
        if (isOp(')')) { p++; break }
        fail()
      }
      return { t: 'call', name: up, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') fail()
      const w2 = toks[p++].v
      misplaced = true
      return rangeNode(tk.v, w2)
    }
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    const a = parseAddr(tk.v)
    if (a) refs.push({ a, b: a })
    return { t: 'ref', a }
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    return { ast, misplaced, refs }
  } catch {
    return null
  }
}

// ---- evaluation
const parsed = new Map()
const memo = new Map()
const active = new Set()

function literal(c) {
  if (c === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(Number(c))
  if (ERRS.has(c)) return err(c)
  return { k: 's', v: c }
}

function getParsed(name) {
  if (!parsed.has(name)) parsed.set(name, parseFormula(cells.get(name).content.slice(1)))
  return parsed.get(name)
}

function cellValue(name) {
  if (!cells.has(name)) return num(0)
  if (memo.has(name)) return memo.get(name)
  if (active.has(name)) return err('#CYCLE!')
  const c = cells.get(name)
  let v
  if (c.content[0] === '=') {
    active.add(name)
    const f = getParsed(name)
    if (!f || f.misplaced) v = err('#ERR!')
    else v = ev(f.ast)
    active.delete(name)
  } else v = literal(c.content)
  memo.set(name, v)
  return v
}

function toNum(v) {
  if (v.k === 'e') return v
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}

function cmpCodePoints(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
const rank = { n: 0, s: 1, b: 2 }
function compare(l, r) {
  if (l.k !== r.k) return rank[l.k] < rank[r.k] ? -1 : 1
  if (l.k === 's') return cmpCodePoints(l.v, r.v)
  const a = Number(l.v), b = Number(r.v)
  return a < b ? -1 : a > b ? 1 : 0
}

function rangeValues(n) {
  if (!n.a || !n.b) return [err('#REF!')]
  const out = []
  const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
  const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push(cellValue(key(c, r)))
  return out
}

function ev(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'ref': return n.a ? cellValue(n.a.name) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(ev(n.e))
      if (v.k === 'e') return v
      return num(n.op === '-' ? -v.v : v.v)
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        return bool(n.op === '=' ? c === 0 : n.op === '<>' ? c !== 0 : n.op === '<' ? c < 0 : n.op === '<=' ? c <= 0 : n.op === '>' ? c > 0 : c >= 0)
      }
      const a = toNum(l), b = toNum(r)
      if (a.k === 'e') return a
      if (b.k === 'e') return b
      let x
      if (n.op === '+') x = a.v + b.v
      else if (n.op === '-') x = a.v - b.v
      else if (n.op === '*') x = a.v * b.v
      else if (n.op === '/') { if (b.v === 0) return err('#DIV/0!'); x = a.v / b.v }
      else x = Math.pow(a.v, b.v)
      return Number.isFinite(x) ? num(x) : err('#DIV/0!')
    }
    case 'call': return call(n)
  }
}

function call(n) {
  const { name, args } = n
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    if (args[0].t === 'range') return err('#VALUE!')
    const c = ev(args[0])
    if (c.k === 'e') return c
    if (c.k === 's') return err('#VALUE!')
    const truthy = c.k === 'b' ? c.v : c.v !== 0
    const br = args[truthy ? 1 : 2]
    return br.t === 'range' ? err('#VALUE!') : ev(br)
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    if (args[0].t === 'range') return err('#VALUE!')
    const v = toNum(ev(args[0]))
    return v.k === 'e' ? v : num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.t === 'range') vals.push(...rangeValues(a))
    else vals.push(ev(a))
  }
  for (const v of vals) if (v.k === 'e') return v
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  let x
  if (name === 'SUM') x = nums.reduce((s, v) => s + v, 0)
  else if (name === 'MIN') x = Math.min(...nums)
  else if (name === 'MAX') x = Math.max(...nums)
  else x = nums.reduce((s, v) => s + v, 0) / nums.length
  return Number.isFinite(x) ? num(x) : err('#DIV/0!')
}

// ---- output
const sorted = [...cells.values()].sort((p, q) => p.a.col - q.a.col || p.a.row - q.a.row)
let out = ''
for (const c of sorted) {
  const name = c.a.name
  if (mode === 'values') {
    const v = cellValue(name)
    let s
    if (v.k === 'n') s = String(Number(v.v.toPrecision(10)))
    else if (v.k === 'b') s = v.v ? 'TRUE' : 'FALSE'
    else s = v.v
    out += `${name}=${s}\n`
  } else {
    const set = new Map()
    if (c.content[0] === '=') {
      const f = getParsed(name)
      if (f) {
        for (const { a, b } of f.refs) {
          for (let col = Math.min(a.col, b.col); col <= Math.max(a.col, b.col); col++)
            for (let row = Math.min(a.row, b.row); row <= Math.max(a.row, b.row); row++) set.set(key(col, row), { col, row })
        }
      }
    }
    const list = [...set.values()].sort((p, q) => p.col - q.col || p.row - q.row)
    out += `${name}:${list.map((x) => ' ' + key(x.col, x.row)).join('')}\n`
  }
}
process.stdout.write(out)
